void U32(std::vector<std::byte>& b,std::size_t o,std::uint32_t v){for(unsigned s=0;s<32;s+=8)b[o++]=std::byte((v>>s)&255);}
std::uint32_t R32(const std::vector<std::byte>& b,std::size_t o){std::uint32_t v{};for(unsigned s=0;s<32;s+=8)v|=std::uint32_t(std::to_integer<unsigned>(b[o++]))<<s;return v;}
std::uint64_t R64(const std::vector<std::byte>& b,std::size_t o){std::uint64_t v{};for(unsigned s=0;s<64;s+=8)v|=std::uint64_t(std::to_integer<unsigned>(b[o++]))<<s;return v;}
std::size_t Toc(const std::vector<std::byte>& b,std::uint32_t type){for(std::size_t i=0;i<R32(b,32);++i){const std::size_t at=64+i*32;if(R32(b,at)==type)return at;}return 0;}
std::size_t Offset(const std::vector<std::byte>& b,std::uint32_t type){const auto at=Toc(b,type);return at?std::size_t(R64(b,at+8)):0;}
